package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.AriaRole;
import java.nio.file.Path;
import java.util.*;
final class CatalogueAssistBrowserAcceptance {
    static void run(BrowserTest h)throws Exception{
        String offering,user="AssistBrowser"+id().substring(0,8);try(var db=h.store.open()){String actor=PlatformFoundationTest.bind(db);Service.createAccount(db,map("name",user,"password",WorkflowSupport.PASSWORD,"role","requester"));offering=Catalogue.save(db,actor,"",CatalogueAcceptance.offering("Reviewed browser service",0,true)).get("offering_id").toString();var questions=List.of(CatalogueQuestionsAcceptance.question("reason","string",true,List.of()),CatalogueQuestionsAcceptance.question("size","choice",true,List.of("Small","Large")),CatalogueQuestionsAcceptance.question("needed","boolean",true,List.of()),CatalogueQuestionsAcceptance.question("date","date",true,List.of()),CatalogueQuestionsAcceptance.question("count","integer",true,List.of()));CatalogueQuestions.save(db,actor,offering,map("revision",1,"questions",questions));String group=Service.create(db,"sys_user_group",map("short_description","Assisted fulfilment"),"admin").get("sys_id").toString();CatalogueRouting.save(db,actor,offering,map("group_id",group,"revision",2));db.connection.commit();}
        long before=CatalogueAssistAcceptance.count(h.store);
        try(var provider=new RecordQuestionsAcceptance.Provider(h.store,h.store.environment);var p=Playwright.create();var browser=p.chromium().launch();var context=browser.newContext()){
            provider.settings.put("AI_CATALOGUE_ENABLED","true");provider.answer.set("Draft <script>safe text</script>");var page=context.newPage();FulfilmentBrowserAcceptance.login(h,page,user);page.navigate(h.base()+"/catalogue/"+offering);page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Describe your request with assistance")).press("Enter");page.getByLabel("Your description").fill("Set up existing equipment");page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Preview what will be sent")).press("Enter");assertEquals(0,provider.calls.get());assertThat(page.locator("main")).containsText(offering);page.getByLabel("Send this description and offering to the configured provider").check();page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Generate an editable draft")).press("Enter");assertEquals(1,provider.calls.get());assertEquals(before,CatalogueAssistAcceptance.count(h.store));assertThat(page.getByLabel("Request details")).hasValue(provider.answer.get());assertThat(page.locator("main script")).hasCount(0);
            page.getByLabel("Request details").fill("Edited and reviewed details <script>");page.getByLabel("Question reason (required)").fill("Approved project");page.getByLabel("Question size (required)").selectOption("Small");page.getByLabel("Question needed (required)").selectOption("true");page.getByLabel("Question date (required)").fill("2026-11-20");page.getByLabel("Question count (required)").fill("2");page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Review this service request")).press("Enter");assertThat(page.getByRole(AriaRole.HEADING,new Page.GetByRoleOptions().setName("Confirm the reviewed request"))).isVisible();assertThat(page.locator("main")).containsText("Edited and reviewed details <script>");assertThat(page.locator("main")).containsText("Approved project");assertEquals(before,CatalogueAssistAcceptance.count(h.store));
            page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Edit reviewed request")).press("Enter");assertThat(page.getByLabel("Request details")).hasValue("Edited and reviewed details <script>");assertThat(page.getByLabel("Question reason (required)")).hasValue("Approved project");assertThat(page.getByLabel("Question size (required)")).hasValue("Small");assertThat(page.getByLabel("Question needed (required)")).hasValue("true");assertThat(page.getByLabel("Question date (required)")).hasValue("2026-11-20");assertThat(page.getByLabel("Question count (required)")).hasValue("2");page.getByLabel("Request details").fill("Final reviewed details <script>");page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Review this service request")).press("Enter");assertEquals(1,provider.calls.get());assertEquals(before,CatalogueAssistAcceptance.count(h.store));
            for(String theme:new String[]{"light","dark"}){if(theme.equals("dark")){page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Dark mode").setExact(true)).click();page.setViewportSize(390,844);}ReleaseBrowserAcceptance.checkAccessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/catalogue-assist-"+theme+".png")).setFullPage(true));}
            new Store(h.store.environment);page.getByLabel("Create this reviewed service request").check();page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Submit reviewed request")).press("Enter");assertTrue(page.url().contains("/record/sc_request/"));assertThat(page.locator("main")).containsText("Final reviewed details <script>");assertThat(page.locator("main")).containsText("Approved project");assertEquals(before+1,CatalogueAssistAcceptance.count(h.store));assertEquals(1,provider.calls.get());ReleaseBrowserAcceptance.checkAccessible(page);
        }
    }
}
